%% QPI LaTeX skeleton (v1.1)
\documentclass[11pt]{article}
\usepackage{amsmath,amsthm,amssymb,mathtools,hyperref}
\title{Quantum Prime Insights (QPI): Color Sieve, Subprime Function, Toroidal Dynamics, and Twin-Prime Structure}
\author{Christopher Michael LeBlanc Sr. (WhyFYI)}
\date{\today}
\theoremstyle{plain}
\newtheorem{theorem}{Theorem}
\newtheorem{lemma}{Lemma}
\newtheorem{conjecture}{Conjecture}
\theoremstyle{definition}
\newtheorem{definition}{Definition}
\begin{document}
\maketitle
\begin{abstract}
We formalize the Quantum Prime Insights (QPI) framework: a 9-column modular lattice with color-coded sieve, a subprime recursion for composite pruning, and a midpoint law that identifies twin primes via red activations. We prove partition correctness and midpoint equivalence, introduce a toroidal embedding with angle-clock phases, and outline two analytic routes toward twin-prime infinitude.\end{abstract}
\section{Lattice, Digital Root, and Toroidal Embedding}
\begin{definition}[Lattice and Digital Root]
Integers $n>1$ are placed on a $9\times N$ grid by column $n\bmod 9$. Define $\mathrm{DR}(n)=1+((n-1)\bmod 9)$.\end{definition}
\begin{definition}[Toroidal Dynamics]
The lattice embeds on a torus. Each successive $9\times 9$ panel advances an inward $9^\circ$ phase; motion also propagates at $\pm45^\circ$ across rows/columns. The node $1$ is a north anchor; $5$ is a local anchor.\end{definition}
\section{QPI Colors, Anchors, and Precedence}
Anchors: $\{1,5\}$. White primes: primes $p\notin\{3,5\}$. Colors: Green (2 or 5, $n>5$), Purple (multiples of 3; include 3 at base), Yellow (Purple with last digit $\in\{0,2,8\}$), Red (Yellow with both neighbors White), Blue (semiprime with factors $\ge7$), Orange ($\ge3$ prime factors, each $\ge7$). Precedence: White $\to$ Red $\to$ Yellow $\to$ Green $\to$ Purple $\to$ Blue $\to$ Orange.\par\noindent\textbf{Correction.} Do not assert the first prime of a twin pair lies in residues $\{0,3,6\} \pmod{9}$. For primes $>3$, divisibility by 3 is impossible; instead, nontrivial twin midpoints are multiples of 3 with last digit in $\{0,2,8\}$.
\section{Structural Results}
\begin{theorem}[Partition Correctness]
Under precedence, the coloring forms a disjoint partition of $\mathbb{N}_{\ge2}$ into White, Red, Yellow, Green, Purple, Blue, Orange (Anchors explicit).\end{theorem}
\begin{lemma}[Subprime Termination and Soundness]
The subprime recursion terminates and never labels a prime; composites with all prime factors $\ge7$ are labeled Blue (exactly two) or Orange ($\ge3$).\end{lemma}
\begin{theorem}[Red Midpoint $\Leftrightarrow$ Twin Primes]
For twins $(p,p+2)$ with $p\ge7$, the midpoint $m=p+1$ is Red iff $p$ and $p+2$ are White.\end{theorem}
\section{Toward Twin-Prime Infinitude}
\begin{conjecture}[QPI Twin Infinitude]
There exist infinitely many Red midpoints; equivalently, infinitely many White twin primes.\end{conjecture}
\subsection{Route I: Density Preservation}
Show admissible Yellow retains positive lower density after removing composites with factors $\ge7$; prove a local independence lemma that yields infinitely many Red activations.
\subsection{Route II: Weighted Sieve on Linear Forms}
Over admissible Yellow, set $L_1(n)=n-1$, $L_2(n)=n+1$ and apply Maynard–Tao style weights refined by QPI pre-sieve to force infinite dual hits.
\section{Computational Protocol}
Segmented sieve (2·3·5 wheel), bit-packed odds, on-demand SPF, and summaries for White/Red/Twins/Yellow/Green/Purple/Blue/Orange with consistency checks.
\end{document}

