7, 109, 113, 127, 131, 137, 139,\n                  149, 151, 157, 163, 167, 173, 179, 181, 191,\n                  193, 197, 199, 211, 223, 227, 229, 233, 239,\n                  241, 251, 257, 263, 269, 271, 277, 281, 283,\n                  293, 307, 311, 313, 317, 331, 337, 347, 349,\n                  353, 359, 367, 373, 379, 383, 389, 397, 401,\n                  409, 419, 421, 431, 433, 439, 443, 449, 457,\n                  461, 463, 467, 479, 487, 491, 499, 503, 509,\n                  521, 523, 541]\n\n\ndef is_prime(n):\n    if n <= 1: return False\n    # A quick standard check\n    for i in range(2, int(math.isqrt(n)) + 1):\n        if n % i == 0:\n            return False\n    return True\n\n\ndef generate_all_products(primes):\n    \"\"\"\n    Generate a set of all composite numbers from primes >= 7.\n    This handles squares of each prime, pairwise products, and iterative expansions\n    to catch higher-level composite structures.\n    \"\"\"\n    products = set()\n\n    # Start with each prime squared\n    for prime in primes:\n        products.add(prime * prime)\n\n    # Multiply each prime with every other prime\n    for i in range(len(primes)):\n        for j in range(i, len(primes)):\n            products.add(primes[i] * primes[j])\n\n    # Multiply resulting products with each prime\n    new_products = list(products)\n    for prime in primes:\n        for product in new_products:\n            products.add(prime * product)\n\n    return sorted(products)\n\n\n# Build the big subprime sets\nall_products = generate_all_products(initial_primes)\n\ndef factorize(n, prime_list):\n    factors = []\n    temp = n\n    for prime in prime_list:\n        if prime > temp:\n            break\n        while temp % prime == 0:\n            factors.append(prime)\n            temp //= prime\n    if temp > 1:\n        factors.append(temp)\n    return factors\n\n\ndef classify_products(products):\n    \"\"\"\n    Classify subprime products as either 'blue' (first-level) or 'orange' (extended).\n    We enforce that 49=7*7 is the first 'blue' product, 343=7*7*7 is the first 'orange'.\n    \"\"\"\n    blue_products = set()\n    orange_products = set()\n\n    # Guarantee these initial references.\n    if 49 in products:\n        blue_products.add(49)\n        products.remove(49)\n    if 343 in products:\n        orange_products.add(343)\n        products.remove(343)\n\n    for product in products:\n        factors = factorize(product, initial_primes)\n        # If it has exactly 2 prime factors (both >=7), we call it 'blue'.\n        if len(factors) == 2 and all(f >= 7 for f in factors):\n            blue_products.add(product)\n        else:\n            # Anything else is 'orange'\n            orange_products.add(product)\n\n    return sorted(blue_products), sorted(orange_products)\n\nblue_products, orange_products = classify_products(all_products)\n\n\ndef color_grid(grid, blue_set, orange_set):\n    rows, cols = grid.shape\n    colors = np.full((rows, cols), 'white', dtype=object)\n\n    for row in range(rows):\n        for col in range(cols):\n            num = grid[row, col]\n\n            # 1) Green if last digit in [0,2,4,5,6,8] and > 5\n            #    This knocks out multiples of 2 and 5 (except for prime 2,5 themselves)\n            if num > 5 and str(num)[-1] in ['0','2','4','5','6','8']:\n                colors[row, col] = 'green'\n\n            # 2) Purple if the column index +1 is multiple of 3 => digital base 3 in 9-wide expansions.\n            #    This knocks out multiples of 3 beyond 3 itself.\n            if ((col+1) % 3 == 0) and num != 3:\n                colors[row, col] = 'purple'\n\n            # 3) Yellow if purple + ends with 0,2,8 => potential twin prime midpoint\n            if colors[row, col] == 'purple' and str(num)[-1] in ['0','2','8']:\n                colors[row, col] = 'yellow'\n\n            # 4) Mark subprime products\n            if num in blue_set:\n                colors[row, col] = 'blue'\n            elif num in orange_set:\n                colors[row, col] = 'orange'\n\n    # Mark actual twin prime midpoints (red) if adjacency check\n    # A 'yellow' cell becomes red if the numbers on both sides are prime.\n    for row in range(rows):\n        for col in range(cols):\n            if colors[row, col] == 'yellow':\n                left_num = grid[row, col-1] if col-1 >= 0 else None\n                right_num = grid[row, col+1] if col+1 < cols else None\n                if left_num and right_num and is_prime(left_num) and is_prime(right_num):\n                    colors[row, col] = 'red'\n\n    return colors\n\n\ndef initialize_grid(rows, cols):\n    return np.arange(1, rows * cols + 1).reshape(rows, cols)\n\n\ndef visualize_grid(rows, cols, blue_set, orange_set, show_plot=True):\n    # Build the grid\n    grid = initialize_grid(rows, cols)\n    # Color it\n    colors = color_grid(grid, blue_set, orange_set)\n\n    # Optional plotting\n    if show_plot:\n        fig, ax = plt.subplots(figsize=(max(8, cols*0.4), max(6, rows*0.4)))\n        table = ax.table(cellText=grid, cellColours=colors, loc='center', cellLoc='center')\n        table.scale(1, 1.5)\n        ax.axis('off')\n        ax.set_title(f\"Zero Point Sieve - {rows}x{cols}\")\n        plt.show()\n\n    # Return the grid and color array for further analysis\n    return grid, colors\n\n\ndef main():\n    print(\"\\n===== Zero Point Prime Sieve & Twin Prime Logic =====\")\n    # Basic input\n    r = int(input(\"Rows: \"))\n    c = int(input(\"Cols (multiple of 9 recommended): \"))\n    grid, colors = visualize_grid(r, c, blue_products, orange_products, show_plot=True)\n    print(\"\\nDone. Primes should be white; twin prime centers red; composites green, purple, blue, or orange.\")\n\nif __name__ == \"__main__\":\n    main()\n",
